function runEvalCommand(options: EvalOptions) {
  const thresholdSpecs = options.threshold ?? [];
  let thresholds: Record<string, number> | undefined;
  if (thresholdSpecs.length) {
    try {
      thresholds = (Eval.parseThresholds as unknown as (specs: string[]) => Record<string, number>)(thresholdSpecs);
    } catch (error) {
      log.error(error instanceof Error ? error.message : String(error));
      process.exitCode = 2;
      return;
    }
  }

  assertFileExists(options.outputs);
  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
    outputsPath: options.outputs,
    referencesPath: options.references
  });
  const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
    outputs: dataset.outputs,
    references: dataset.references
  });

  if (thresholds) {
    try {
      (Eval.validateThresholds as unknown as (config: unknown) => void)({ evaluations, thresholds });
    } catch (error) {
      log.error(error instanceof Error ? error.message : String(error));
      process.exitCode = 2;
      return;
    }
  }

  const report = (Eval.generateReport as unknown as (config: unknown) => any)({
    evaluations,
    outputsPath: dataset.outputsPath,
    referencesPath: dataset.referencesPath,
    thresholds
  });
  const resolvedPath = (Eval.writeReport as unknown as (config: unknown) => string)({
    report,
    format: options.format ?? 'json',
    reportPath: options.report
  });
  log.success('Evaluation report generated.', { path: resolvedPath });

  if (thresholds) {
    const failed = (report.thresholds as Array<{ metric: string; min: number; score: number | null; passed: boolean }>)
      .filter((threshold) => !threshold.passed);
    if (failed.length) {
      log.error('Evaluation thresholds failed.', { failed });
      process.exitCode = 1;
    } else {
      log.success('All evaluation thresholds passed.', { thresholds: report.thresholds });
    }
  }
}

