describe('Evaluation thresholds', () => {
  const baseReport = (evaluations, thresholds) =>
    generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      generatedAt: '2024-01-01T00:00:00.000Z',
      thresholds
    });

  it('leaves reports unchanged when no thresholds are given', () => {
    const evaluations = runEvaluations({ outputs: ['Hello'], references: ['hello'] });
    const report = baseReport(evaluations);
    expect(Object.keys(report)).toEqual(['metadata', 'metrics']);
    expect(toMarkdown(report)).not.toContain('Thresholds');
  });

  it('passes when every score is at least its minimum', () => {
    const evaluations = runEvaluations({ outputs: ['a', 'b'], references: ['a', 'c'] });
    const report = baseReport(evaluations, { exact_match: 0.5 });
    expect(report.passed).toBe(true);
    expect(report.thresholds).toEqual([{ metric: 'exact_match', min: 0.5, score: 0.5, passed: true }]);
  });

  it('fails when any score is below its minimum', () => {
    const evaluations = runEvaluations({ outputs: ['a', 'b'], references: ['a', 'c'] });
    const report = baseReport(evaluations, { exact_match: 0.9, length_variance: 0.5 });
    expect(report.passed).toBe(false);
    expect(report.thresholds).toEqual([
      { metric: 'exact_match', min: 0.9, score: 0.5, passed: false },
      { metric: 'length_variance', min: 0.5, score: 1, passed: true }
    ]);

    const markdown = toMarkdown(report);
    expect(markdown).toContain('## Thresholds');
    expect(markdown).toContain('- **Result:** FAIL');
    expect(markdown).toContain('- **exact_match:** FAIL (score 0.5, min 0.9)');
    expect(markdown).toContain('- **length_variance:** PASS (score 1, min 0.5)');
  });

  it('fails a threshold whose metric has no score', () => {
    const evaluations = runEvaluations({ outputs: ['a'] });
    const report = baseReport(evaluations, { exact_match: 0 });
    expect(report.passed).toBe(false);
    expect(report.thresholds).toEqual([{ metric: 'exact_match', min: 0, score: null, passed: false }]);
    expect(toMarkdown(report)).toContain('- **exact_match:** FAIL (score n/a, min 0)');
  });

  it('supports custom metrics', () => {
    const customMetric = () => ({ id: 'politeness', label: 'Politeness', score: 0.8, total: 1 });
    const evaluations = runEvaluations({ outputs: ['please'], metrics: [customMetric] });
    const report = baseReport(evaluations, { politeness: 0.75 });
    expect(report.passed).toBe(true);
    expect(report.thresholds).toEqual([{ metric: 'politeness', min: 0.75, score: 0.8, passed: true }]);
  });

  it('rejects unknown metric ids and listing the valid ones', () => {
    const evaluations = runEvaluations({ outputs: ['a'], references: ['a'] });
    expect(() => baseReport(evaluations, { bleu: 0.5 })).toThrow(
      'Unknown metric "bleu" in thresholds. Valid metric ids: exact_match, toxicity, length_variance.'
    );
  });

  it('rejects minimums outside 0 to 1', () => {
    const evaluations = runEvaluations({ outputs: ['a'], references: ['a'] });
    expect(() => baseReport(evaluations, { exact_match: 1.5 })).toThrow('between 0 and 1');
    expect(() => baseReport(evaluations, { exact_match: '0.5' })).toThrow('between 0 and 1');
  });

  it('parses CLI threshold specs', () => {
    expect(parseThresholds(['exact_match=0.9', 'toxicity=1'])).toEqual({ exact_match: 0.9, toxicity: 1 });
    expect(parseThresholds([])).toEqual({});
    expect(() => parseThresholds(['exact_match'])).toThrow('expected <metric>=<number>');
    expect(() => parseThresholds(['exact_match='])).toThrow('expected <metric>=<number>');
    expect(() => parseThresholds(['=0.5'])).toThrow('expected <metric>=<number>');
    expect(() => parseThresholds(['exact_match=abc'])).toThrow('expected <metric>=<number>');
    expect(() => parseThresholds(['exact_match=1.2'])).toThrow('minimum must be between 0 and 1');
    expect(() => parseThresholds(['exact_match=-0.1'])).toThrow('minimum must be between 0 and 1');
    expect(() => parseThresholds(['exact_match=0.5', 'exact_match=0.6'])).toThrow('already given');
  });
});

